//! 🧪️ Official Unicode16 boundaries share pinned portable authority and preserve borrowed sources through controlled retirement.
use super::*;
use semio_framework_2d_text_font_testing::close;
fn authorities()->(AdmittedLineBreak<Vec<u8>>,super::super::AdmittedUnicode<Vec<u8>>){let mut line=LineBreakDataAdmissionJob::new(LINE_BREAK_BYTES.to_vec(),1000000);while !line.advance(7,&mut fixture_work()).unwrap().done{}let admitted=line.take_result().unwrap();close(line);let mut unicode=super::super::UnicodeDataAdmissionJob::new(super::super::UNICODE_BYTES.to_vec(),1000000);while !unicode.advance(4096,&mut fixture_work()).unwrap().done{}let output=unicode.take_result().unwrap();close(unicode);(admitted,output)}
#[test]
fn official_unicode16_line_break_corpus(){let(line,unicode)=authorities();let mut count=0;for record in include_str!("🧫️fixtures/LineBreakTest-16.0.0.txt").lines(){let body=record.split('#').next().unwrap().trim();if body.is_empty(){continue;}let mut source=String::new();let mut expected=Vec::new();for token in body.split_whitespace(){if token=="÷"{if !source.is_empty(){expected.push(source.len());}}else if token!="×"{source.push(char::from_u32(u32::from_str_radix(token,16).unwrap()).unwrap());}}let mut cursor=UnicodeLineBreakCursor::new(&source,line.layout,&line.source,unicode.layout,&unicode.source,1048576,1000000000);while !cursor.advance(&source,&line.source,&unicode.source,4096,&mut fixture_work()).unwrap().done{}assert_eq!(cursor.result().unwrap().iter().map(|point|point.at).collect::<Vec<_>>(),expected,"{record}");close(cursor);count+=1;}assert_eq!(count,16672);close(line);close(unicode);}
#[test]
fn grants_original_sources_and_partial_retirement(){let(line,unicode)=authorities();let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){for grant in [1,7,4096]{let text=row["text"].as_str().unwrap();let mut cursor=UnicodeLineBreakCursor::new(text,line.layout,&line.source,unicode.layout,&unicode.source,1048576,1000000000);while !cursor.advance(text,&line.source,&unicode.source,grant,&mut fixture_work()).unwrap().done{}let actual=cursor.result().unwrap().iter().map(|point|serde_json::json!({"at":point.at,"mandatory":point.mandatory})).collect::<Vec<_>>();assert_eq!(actual,*row["expected"].as_array().unwrap());close(cursor);}}let source=String::from("a b\r\n中文");for grant in [1,7,4096]{let mut cursor=UnicodeLineBreakCursor::new(&source,line.layout,&line.source,unicode.layout,&unicode.source,1048576,1000000000);let mut work=0;loop{let(progress,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(&source,&line.source,&unicode.source,grant,&mut fixture_work()).unwrap());assert_eq!(physical.released_bytes,0);assert!(progress.work-work<=grant as u64);work=progress.work;if progress.done{break;}}assert_eq!(cursor.result().unwrap().iter().map(|point|point.at).collect::<Vec<_>>(),vec![2,5,8,11]);let output=cursor.take_result().unwrap();close(cursor);close(output);}for stop in [0,1,7,32,90,180]{let mut cursor=UnicodeLineBreakCursor::new(&source,line.layout,&line.source,unicode.layout,&unicode.source,1048576,1000000000);if stop>0{cursor.advance(&source,&line.source,&unicode.source,stop,&mut fixture_work()).unwrap();}cursor.cancel();assert!(cursor.result().is_err());close(cursor);}let mut changed=UnicodeLineBreakCursor::new(&source,line.layout,&line.source,unicode.layout,&unicode.source,1048576,1000000000);assert!(changed.advance(&source,&line.source.clone(),&unicode.source,1).is_err());assert!(changed.advance(&source,&line.source,&unicode.source,0).is_err());close(changed);close(line);close(unicode);}
#[test]
fn malformed_property_authorities_refuse(){assert!(PropertyCursor::new(LineBreakLayout{count:1,byte_length:36},0xd800).is_err());for(at,value)in [(0,0),(5,0),(19,0),(20,1),(32,48),(33,2),(34,1),(27,1),(39,0)]{let mut bytes=LINE_BREAK_BYTES.to_vec();bytes[at]=value;let mut job=LineBreakDataAdmissionJob::new(bytes,1000000);assert!((||{while !job.advance(7)?.done{}Ok::<(),String>(())})().is_err());close(job);}let mut truncated=LineBreakDataAdmissionJob::new(LINE_BREAK_BYTES[..LINE_BREAK_BYTES.len()-1].to_vec(),1000000);assert!(truncated.advance(1).is_err());close(truncated);}

fn fixture_work()->semio_framework_2d_text_font::work::FontWorkLedger{semio_framework_2d_text_font::work::FontWorkLedger::new(semio_framework_value::RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:16777216,maximum_capacity_bytes:67108864,maximum_release_bytes:67108864,maximum_depth:128})}
